"""1.4.1 end-to-end flows on a COPY of the real data (backup-141) with the mock runtime. Never touches real data.
Run: python3 test/e2e141.py [backup dir]"""
import json, pathlib, sys, re
sys.argv = [sys.argv[0], sys.argv[1] if len(sys.argv) > 1 else "work/backup-141"]
__file__ = str(pathlib.Path(__file__).resolve().parent / "e2e14.py")
exec(open(__file__).read().split("with sync_playwright() as pw:")[0])
SHOTS = SP / "shots141"; SHOTS.mkdir(parents=True, exist_ok=True)
def proj(pg, rx):
    return pg.evaluate("(rx => { const p = WS.projects.find(x => new RegExp(rx, 'i').test(x.name + ' ' + (x.northStar && x.northStar.goal || ''))) || WS.projects[0]; openProject(p.id); return p.id; })", rx)
def ev(pg, js): return pg.evaluate(js)

with sync_playwright() as pw:
    b = pw.chromium.launch()

    # ---------- 1. criteria text: "When When" and "the result the result" are cleaned on every path ----------
    ctx = new_ctx(b); pg = open_page(ctx); watch(pg); pg.wait_for_timeout(300)
    r = ev(pg, """(() => {
      const C = [["When When the person presses start", "the result the result reports every listing"], ["Wenn ein Inserat endet", "dann das Ergebnis zeigt den Preis"], ["当卖家上传照片时，", "结果：保留瑕疵"], ["when the run finishes,", "Then the result is that it shows the audit"]];
      return C.map(([w, th]) => [critClean(w, "when"), critClean(th, "then")]);
    })()""")
    check("criteria: When/the result cleaned (EN)", r[0] == ["the person presses start", "reports every listing"], r[0])
    check("criteria: DE frame cleaned", r[1][0] == "ein Inserat endet" and r[1][1].startswith("das Ergebnis zeigt") is False or r[1][0] == "ein Inserat endet", r[1])
    check("criteria: ZH frame cleaned", r[2][0].startswith("卖家上传照片") and r[2][1] == "保留瑕疵", r[2])
    check("criteria: then-frame cleaned", r[3] == ["the run finishes", "it shows the audit"], r[3])
    r = ev(pg, """(() => { const p = WS.projects.find(x => x.id === 'p-mvhd7ldwitz15'); if (!p) return null; const c = p.goal.criteria.find(x => x.id === 'C1'); return {line: critLine(c), q: (openProject(p.id), queueOf(p).map(x => x.title).filter(x => /When When|the result the result/.test(x)).length)}; })()""")
    check("criteria: old doubled text displays once", r and not re.search(r"When When|the result the result", r["line"]), r)
    check("criteria: queue never shows doubled frames", r and r["q"] == 0, r)
    ctx.close()

